-- =====================================================================
-- Fusing / machine-block helper (used by scanAllPets)
-- =====================================================================
local _BLOCKING_MACHINE_TYPES = {
    Fuse     = true,
    Duel     = true,
    Trade    = true,
    Crafting = true,
}
local function _VanishIsFusing(animalData)
    if type(animalData) ~= "table" then return false end
