    C = {{coord=Vector3.new(-476,-3.048217,7),facing="EAST"},{coord=Vector3.new(-342,-3.048217,6),facing="WEST"},{coord=Vector3.new(-476,-3.048217,114),facing="EAST"},{coord=Vector3.new(-342,-3.048217,114),facing="WEST"}},
