        local lastPct = -1
        while hudProgressFill and hudProgressFill.Parent do
            task.wait(0.05)
            local pct = math.clamp(math.floor((hudProgressFill.Size.X.Scale * 100) + 0.5), 0, 100)
            if pct ~= lastPct then
                hudPercent.Text = tostring(pct) .. "%"
                lastPct = pct
            end
        end
    end)
    
