    syncAutoStealEnabledFromModes()
    _G.NEAREST_INSTANT_MODE = (stealNearestEnabled and instantStealEnabled)
    SaveConfig()
    SharedState.ListNeedsRedraw = false; updateUI(autoStealEnabled, get_all_pets())
end)


