        lbl.Size = UDim2.new(1, -(s(67) + s(14)), 1, 0)
        lbl.Text = text
        lbl.Font = Enum.Font.GothamMedium
        lbl.TextSize = s(14)
        lbl.TextColor3 = HAZE.TEXT
        lbl.TextXAlignment = Enum.TextXAlignment.Left
        lbl.Parent = row

        return row
    end

