                    local t = d.Text
                    if t and t ~= "" then
                        displayName = t
                    end
                elseif d.Name == "Generation" then
                    local t = d.Text
                    if t and t ~= "" then
                        generation = t
                    end
                end

                if displayName and generation then
                    break
                end
            end
        end

        return displayName, generation
    end

    local function getMutationColor(mut)
