        container.BackgroundTransparency = 0.45
        container.BorderSizePixel = 0
        Instance.new("UICorner", container).CornerRadius = UDim.new(0, 6)

        local strokeColor = Color3.fromRGB(60, 60, 60)

        local stroke = Instance.new("UIStroke")
