                end
            end
            GriefConnections = {}
            if GriefScreenGui then
                pcall(function() GriefScreenGui:Destroy() end)
                GriefScreenGui = nil
            end
            _G.GriefDetectorTest = nil
        end

        _G.GriefDetectorSetEnabled = function(enabled)
            if enabled then
