        Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)

        local function setSliderFromVal(v)
            v = math.clamp(v, SPEED_MIN, SPEED_MAX)
            _spVal = math.floor(v)
            local pct = (_spVal - SPEED_MIN) / (SPEED_MAX - SPEED_MIN)
            sliderFill.Size  = UDim2.new(pct, 0, 1, 0)
            knob.Position    = UDim2.new(0, pct * TRACK_W - 8, 0.5, -8)
            speedValLbl.Text = "Speed: " .. _spVal
            if _spOn then _setWalkSpeed(_spVal) end
        end
        setSliderFromVal(_spVal)

        local sliderDragging = false
        local function updateFromInput(i)
            local ap = track.AbsolutePosition
            local as = track.AbsoluteSize
            local rx = math.clamp(i.Position.X - ap.X, 0, as.X)
            setSliderFromVal(SPEED_MIN + (rx / as.X) * (SPEED_MAX - SPEED_MIN))
        end
        track.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 then
                sliderDragging = true; updateFromInput(i)
            end
        end)
        track.InputChanged:Connect(function(i)
            if sliderDragging and i.UserInputType == Enum.UserInputType.MouseMovement then updateFromInput(i) end
        end)
        track.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 then sliderDragging = false end
        end)

        do
            local presets = {16, 18, 20, 24}
