                pb.Font             = Enum.Font.Gotham
                pb.TextSize         = 11
                pb.ZIndex           = 52
                Instance.new("UICorner", pb).CornerRadius = UDim.new(0, 5)
                pb.MouseButton1Click:Connect(function() setSliderFromVal(v) end)
            end
        end

        do
            local lbl = Instance.new("TextLabel", win)
            lbl.Size = UDim2.new(0, 80, 0, 24); lbl.Position = UDim2.new(0, 10, 0, 104)
