            lbl.TextColor3 = Color3.fromRGB(170, 170, 205); lbl.Font = Enum.Font.Gotham
            lbl.TextSize = 12; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.ZIndex = 51
        end
        pill = Instance.new("Frame", win)
        pill.Size = UDim2.new(0, 44, 0, 24); pill.Position = UDim2.new(1, -54, 0, 104)
