        -- Toggle dans les settings (row 8) : ouvre/ferme panel ET active/désactive speed
        local ok2, spBtn, spSet = pcall(makeMainToggle, "Speed Boost", _MT_START + (_MT_ROW + _MT_GAP) * 8, false)
