-- ── Grab Own Base (row 8) ────────────────────────────────────────────────────
task.defer(function()
    pcall(function()
        local _gobRunning = false

        local function _gobFindMyPlots()
            local plots = Workspace:FindFirstChild("Plots")
            local mine = {}
            if not plots then return mine end
            for _, plot in ipairs(plots:GetChildren()) do
                local sign = plot:FindFirstChild("PlotSign")
                if sign then
                    local yb = sign:FindFirstChild("YourBase")
                    if yb and yb:IsA("BillboardGui") and yb.Enabled then
                        table.insert(mine, plot); continue
                    end
                    for _, d in ipairs(sign:GetDescendants()) do
                        if d:IsA("TextLabel") then
                            local t = d.Text:lower()
                            if t:find(LocalPlayer.Name:lower(), 1, true)
                            or t:find(LocalPlayer.DisplayName:lower(), 1, true) then
                                table.insert(mine, plot); break
                            end
                        end
                    end
                end
            end
            return mine
        end

        local function _gobGetPodiumPos(podium)
            local base  = podium:FindFirstChild("Base")
            local spawn = base and base:FindFirstChild("Spawn")
            if spawn then return spawn.CFrame end
            if base then return base.CFrame end
            local ok, cf = pcall(function() return podium:GetPivot() end)
            if ok then return cf end
            return nil
        end

        local function _gobGrabAll()
            if _gobRunning then return end
            _gobRunning = true
            pcall(function()
                local myPlots = _gobFindMyPlots()
                for _, plot in ipairs(myPlots) do
                    local podiums = plot:FindFirstChild("AnimalPodiums")
                    if not podiums then continue end
                    for _, podium in ipairs(podiums:GetChildren()) do
                        -- collect all prompts first
                        local prompts = {}
                        for _, desc in ipairs(podium:GetDescendants()) do
                            if desc:IsA("ProximityPrompt") and desc.Enabled then
                                table.insert(prompts, desc)
                            end
                        end
                        if #prompts == 0 then continue end
                        -- TP near the podium
                        local cf = _gobGetPodiumPos(podium)
                        if cf then
                            local char = LocalPlayer.Character
                            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                pcall(function()
                                    hrp.CFrame = cf * CFrame.new(0, 3, 3)
                                end)
                                task.wait(0.08)
                            end
                        end
                        -- fire each prompt
                        for _, pp in ipairs(prompts) do
                            pcall(function()
                                if fireproximityprompt then
                                    fireproximityprompt(pp)
                                end
                            end)
                            task.wait(0.05)
                        end
                    end
                end
            end)
            _gobRunning = false
        end

        local ok9, gobBtn, gobSet = pcall(makeMainToggle, "Grab Own Base",
            _MT_START + (_MT_ROW + _MT_GAP) * 8, false)
        if ok9 and gobBtn then
            -- Popup UI
            local _gobPopup = nil
            local _gobActive = false
            local function _closeGobPopup(keepActive)
                if _gobPopup and _gobPopup.Parent then _gobPopup:Destroy() end
                _gobPopup = nil
                if not keepActive then _gobActive = false; gobSet(false) end
            end
            local function _openGobPopup()
                -- Si déjà actif : désactiver
                if _gobActive then _closeGobPopup(false); return end
                if _gobPopup then _closeGobPopup(false); return end
                gobSet(true); _gobActive = true
                local sg = Instance.new("ScreenGui")
                sg.Name = "GobPopup"; sg.ResetOnSpawn = false; sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                local _sgOk = pcall(function() sg.Parent = game:GetService("CoreGui") end)
                if not _sgOk or not sg.Parent then
                    pcall(function() sg.Parent = gethui and gethui() or game:GetService("Players").LocalPlayer.PlayerGui end)
                end
                if protect_gui then pcall(function() protect_gui(sg) end) end
                _gobPopup = sg

                local pop = Instance.new("Frame", sg)
                pop.Size = UDim2.new(0, 160, 0, 56)
                pop.AnchorPoint = Vector2.new(0.5, 0.5)
                pop.Position = UDim2.new(0.5, 0, 0.5, 0)
                pop.BackgroundColor3 = Color3.fromRGB(8, 10, 18)
                pop.BackgroundTransparency = 0.25
                pop.BorderSizePixel = 0
                pop.ClipsDescendants = false
                Instance.new("UICorner", pop).CornerRadius = UDim.new(0, 8)
                -- Stroke animé thème
                local popStroke = Instance.new("UIStroke", pop)
                popStroke.Thickness = 1.5
                if _G._FH_AddThemeStroke then _G._FH_AddThemeStroke(popStroke)
                else popStroke.Color = _G._FH_AccentA or Color3.fromRGB(60, 210, 100) end

                -- Étoiles flottantes (même pattern que les autres panels)
                local _starData = {{0.12,0.30,2,0.0048},{0.45,0.65,3,0.0055},{0.78,0.20,2,0.0042},{0.33,0.80,3,0.0051},{0.66,0.45,2,0.0039},{0.90,0.70,3,0.0060},{0.22,0.55,2,0.0044}}
                local _starF, _starO = {}, {}
                for i, sp in ipairs(_starData) do
                    local s = Instance.new("Frame", pop)
                    s.Size = UDim2.new(0, sp[3], 0, sp[3])
                    s.Position = UDim2.new(sp[1], 0, sp[2], 0)
                    s.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                    s.BackgroundTransparency = 0.3; s.BorderSizePixel = 0; s.ZIndex = 10
                    Instance.new("UICorner", s).CornerRadius = UDim.new(1, 0)
                    _starF[i] = s; _starO[i] = sp[1]
                end
                game:GetService("RunService").Heartbeat:Connect(function(dt)
                    for i, s in ipairs(_starF) do
                        if not s or not s.Parent then continue end
                        _starO[i] = (_starO[i] - _starData[i][4] * dt) % 1
                        s.Position = UDim2.new(_starO[i], 0, _starData[i][2], 0)
                        s.BackgroundTransparency = 0.3 + math.abs(math.sin(tick() * 0.8 + i * 0.7)) * 0.5
                    end
                end)

                -- Bouton GRAB
                local grabBtn = Instance.new("TextButton", pop)
                grabBtn.Size = UDim2.new(1, -16, 0, 30)
                grabBtn.Position = UDim2.new(0, 8, 0, 13)
                grabBtn.BackgroundColor3 = _G._FH_AccentA or Color3.fromRGB(60, 210, 100)
                grabBtn.BorderSizePixel = 0
                grabBtn.Text = "GRAB"
                grabBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                grabBtn.Font = Enum.Font.GothamBold
                grabBtn.TextSize = 12
                grabBtn.AutoButtonColor = false
                Instance.new("UICorner", grabBtn).CornerRadius = UDim.new(0, 7)
                if _G._FH_AddThemeFill then _G._FH_AddThemeFill(grabBtn)
                else grabBtn.BackgroundColor3 = _G._FH_AccentA or Color3.fromRGB(60, 210, 100) end

                grabBtn.MouseButton1Click:Connect(function()
                    task.spawn(function() _gobGrabAll() end)
                end)

                -- Drag
                local _dragging, _dragStart, _popStart = false, nil, nil
                pop.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                        _dragging = true
                        _dragStart = inp.Position
                        _popStart = pop.Position
                        inp.Changed:Connect(function()
                            if inp.UserInputState == Enum.UserInputState.End then _dragging = false end
                        end)
                    end
                end)
                game:GetService("UserInputService").InputChanged:Connect(function(inp)
                    if _dragging and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
                        local delta = inp.Position - _dragStart
                        pop.Position = UDim2.new(
                            _popStart.X.Scale, _popStart.X.Offset + delta.X,
                            _popStart.Y.Scale, _popStart.Y.Offset + delta.Y
                        )
                    end
                end)
            end

            gobBtn.MouseButton1Click:Connect(_openGobPopup)
        end
    end)
end)

-- ── Game Stretcher (row 9) ───────────────────────────────────────────────────
task.defer(function()
    pcall(function()
        local _gsEnabled   = false
        local STRETCH_NAME = "FH_GameStretch3"
        local STRETCH_MAT  = CFrame.new(0, 0, 0, 1, 0, 0, 0, 0.8, 0, 0, 0, 1)
        local RS = game:GetService("RunService")

        local function enableStretcher()
            if _gsEnabled then return end
            _gsEnabled = true
            pcall(function() RS:UnbindFromRenderStep(STRETCH_NAME) end)
            pcall(function()
                RS:BindToRenderStep(STRETCH_NAME, 2001, function()
                    local cam = workspace.CurrentCamera
                    if cam then cam.CFrame = cam.CFrame * STRETCH_MAT end
                end)
            end)
        end

        local function disableStretcher()
            if not _gsEnabled then return end
            _gsEnabled = false
            pcall(function() RS:UnbindFromRenderStep(STRETCH_NAME) end)
        end

        local ok9, gsBtn, gsSet = pcall(makeMainToggle, "Game Stretcher",
            _MT_START + (_MT_ROW + _MT_GAP) * 9, false)
        if ok9 and gsBtn then
            gsBtn.MouseButton1Click:Connect(function()
                if _gsEnabled then
                    disableStretcher()
                else
                    enableStretcher()
                end
                gsSet(_gsEnabled)
                pcall(function() SettingsObj:SetAttribute("SavedGameStretcher", _gsEnabled) end)
            end)
            pcall(function()
                local sv = SettingsObj:GetAttribute("SavedGameStretcher")
                if sv == true then
                    enableStretcher()
                    gsSet(true)
                end
            end)
        end
    end)
end)

-- ── 1. AUTO STEAL ─────────────────────────────────────────────────────────────
-- Controls whether the Steal Target panel's auto-steal is active.
-- Uses the existing _G.AutoStealEnable / _G.AutoStealDisable API.
local _autoStealSettingOn = true   -- default: on (matches script startup behaviour)
_G._autoStealSettingOn = _autoStealSettingOn

local asBtn, asSet = makeMainToggle("Auto Steal", _MT_START, _autoStealSettingOn)
asBtn.MouseButton1Click:Connect(function()
    _autoStealSettingOn = not _autoStealSettingOn
    _G._autoStealSettingOn = _autoStealSettingOn
    asSet(_autoStealSettingOn)
    if _autoStealSettingOn then
        if _G.AutoStealEnable then pcall(_G.AutoStealEnable) end
    else
        if _G.AutoStealDisable then pcall(_G.AutoStealDisable) end
    end
    pcall(function() SettingsObj:SetAttribute("SavedAutoSteal", _autoStealSettingOn) end)
end)
-- Restore saved state
pcall(function()
    local saved = SettingsObj:GetAttribute("SavedAutoSteal")
    if saved ~= nil then
        _autoStealSettingOn = saved
        _G._autoStealSettingOn = saved
        asSet(saved)
        if not saved and _G.AutoStealDisable then pcall(_G.AutoStealDisable) end
    end
end)


-- ── 3. AUTO TP ON JOIN ────────────────────────────────────────────────────────
-- When enabled: the TP module's first-character auto-snipe fires on join.
-- When disabled: the join snipe is suppressed (flag read by onCharacterSpawn).
-- Anti-Bee & Anti-Disco
local AntiBeeDisco = {
    running = false,
    connections = {},
    originalMoveFunction = nil,
    controlsProtected = false,
    badLightingNames = { Blue = true, DiscoEffect = true, BeeBlur = true, ColorCorrection = true },
}

function AntiBeeDisco:nuke(obj)
    if not obj or not obj.Parent then return end
    if self.badLightingNames[obj.Name] then
        pcall(function() obj:Destroy() end)
    end
end

function AntiBeeDisco:disconnectAll()
    for _, conn in ipairs(self.connections) do
        if typeof(conn) == "RBXScriptConnection" then
            pcall(function() conn:Disconnect() end)
        end
    end
    self.connections = {}
end

function AntiBeeDisco:protectControls()
    if self.controlsProtected then return end
    pcall(function()
        local PlayerScripts = LocalPlayer:FindFirstChild("PlayerScripts")
        local PlayerModule = PlayerScripts and PlayerScripts:FindFirstChild("PlayerModule")
        if not PlayerModule then return end
        local Controls = require(PlayerModule):GetControls()
        if not Controls then return end

        if not self.originalMoveFunction then
            self.originalMoveFunction = Controls.moveFunction
        end

        local function protectedMoveFunction(ctrlSelf, moveVector, relativeToCamera)
            if self.originalMoveFunction then
                self.originalMoveFunction(ctrlSelf, moveVector, relativeToCamera)
            end
        end

        table.insert(self.connections, RunService.Heartbeat:Connect(function()
            if not self.running then return end
            if Controls.moveFunction ~= protectedMoveFunction then
                Controls.moveFunction = protectedMoveFunction
            end
        end))

        Controls.moveFunction = protectedMoveFunction
        self.controlsProtected = true
    end)
end

function AntiBeeDisco:restoreControls()
    if not self.controlsProtected then return end
    pcall(function()
        local PlayerScripts = LocalPlayer:FindFirstChild("PlayerScripts")
        local PlayerModule = PlayerScripts and PlayerScripts:FindFirstChild("PlayerModule")
        if not PlayerModule then return end
        local Controls = require(PlayerModule):GetControls()
        if Controls and self.originalMoveFunction then
            Controls.moveFunction = self.originalMoveFunction
            self.controlsProtected = false
        end
    end)
end

function AntiBeeDisco:blockBuzzingSound()
    pcall(function()
        local playerScripts = LocalPlayer:FindFirstChild("PlayerScripts")
        local beeScript = playerScripts and playerScripts:FindFirstChild("Bee", true)
        if beeScript then
            local buzzing = beeScript:FindFirstChild("Buzzing")
            if buzzing and buzzing:IsA("Sound") then
                buzzing:Stop()
                buzzing.Volume = 0
            end
        end
    end)
end

function AntiBeeDisco:Enable()
    if self.running then return end
    self.running = true

    for _, inst in ipairs(Lighting:GetDescendants()) do
        self:nuke(inst)
    end

    table.insert(self.connections, Lighting.DescendantAdded:Connect(function(obj)
        if not self.running then return end
        self:nuke(obj)
    end))

    self:protectControls()

    table.insert(self.connections, RunService.Heartbeat:Connect(function()
        if not self.running then return end
        self:blockBuzzingSound()
    end))
end

function AntiBeeDisco:Disable()
    if not self.running then return end
    self.running = false
    self:restoreControls()
    self:disconnectAll()
end

_G.ANTI_BEE_DISCO = AntiBeeDisco

local _antiBeeDiscoOn = false
local abdBtn, abdSet = makeMainToggle("Anti-Bee & Disco", _MT_START + (_MT_ROW + _MT_GAP), _antiBeeDiscoOn)
abdBtn.MouseButton1Click:Connect(function()
