    else
        AntiBeeDisco:Disable()
    end
    pcall(function() SettingsObj:SetAttribute("SavedAntiBeeDisco", _antiBeeDiscoOn) end)
end)

pcall(function()
    local saved = SettingsObj:GetAttribute("SavedAntiBeeDisco")
    if saved == true then
        _antiBeeDiscoOn = true
        abdSet(true)
        AntiBeeDisco:Enable()
    end
end)

