-- ── ANTI BODY SWAP (ported from dtc.txt) ────────────────────────────────────
-- Detects another player swapping into your body with a Body Swap Potion and
-- automatically swaps back. Always wired; gate on/off via _G.AntiBodySwapEnabled.
if _G.AntiBodySwapEnabled == nil then _G.AntiBodySwapEnabled = true end
task.spawn(function()
    local _abs_POTION_NAME     = "Body Swap Potion"
    local _abs_HOLDER_JUMP_MIN = 3
    local _abs_SWAP_RADIUS     = 5
    local _abs_LOCAL_MOVED_MIN = 3
    local _abs_PER_PLAYER_CD   = 30

    local Players     = game:GetService("Players")
    local RunService  = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer

    local hitCooldowns   = {}
    local localJustFired = false
    local prevHolderPos  = nil
    local prevLocalPos   = nil

    local function getLocalHRP()
        local char = LocalPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end

    local function getHolder()
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer
               and plr.Character
               and plr.Character:FindFirstChild(_abs_POTION_NAME) then
                return plr
            end
        end
        return nil
    end

    local function hookLocalPotion()
        local char = LocalPlayer.Character
        if not char then return end
        local function hook(potion)
            potion.Activated:Connect(function()
                localJustFired = true
                task.delay(1, function() localJustFired = false end)
            end)
        end
        local existing = char:FindFirstChild(_abs_POTION_NAME)
        if existing then hook(existing) end
        char.ChildAdded:Connect(function(child)
            if child.Name == _abs_POTION_NAME then hook(child) end
        end)
    end
    LocalPlayer.CharacterAdded:Connect(function()
        task.wait(0.1)
        hookLocalPotion()
    end)
    hookLocalPotion()

    local function swapBack(targetPlayer)
        pcall(function()
            local char = LocalPlayer.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum then return end

            local potion = char:FindFirstChild(_abs_POTION_NAME)
                        or (LocalPlayer:FindFirstChild("Backpack") and LocalPlayer.Backpack:FindFirstChild(_abs_POTION_NAME))
            if not potion then return end

            hum:EquipTool(potion)
            task.wait(0.05)

            local targetChar = targetPlayer.Character
            local targetHRP  = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
            local localHRP   = getLocalHRP()
            if targetHRP and localHRP then
                localHRP.CFrame = CFrame.lookAt(
                    targetHRP.Position,
                    targetHRP.Position + targetHRP.CFrame.LookVector
                )
            end

            if LocalPlayer:GetAttribute("Stealing") then
                while LocalPlayer:GetAttribute("Stealing") do task.wait() end
                task.wait(0.2)
                hum:EquipTool(potion)
                task.wait(0.05)
                if targetPlayer.Character then
                    local tHRP = targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                    local lHRP = getLocalHRP()
                    if tHRP and lHRP then
                        lHRP.CFrame = CFrame.lookAt(
                            tHRP.Position,
                            tHRP.Position + tHRP.CFrame.LookVector
                        )
                    end
                end
            end

            potion = char:FindFirstChild(_abs_POTION_NAME)
            if potion then potion:Activate() end
        end)
    end

    RunService.Heartbeat:Connect(function()
        if not _G.AntiBodySwapEnabled then
            prevHolderPos = nil
            prevLocalPos  = nil
            return
        end

        local holder = getHolder()
        if not holder then
            prevHolderPos = nil
            prevLocalPos  = nil
            return
        end

        local cd = hitCooldowns[holder.Name]
        if cd and tick() - cd < _abs_PER_PLAYER_CD then return end

        local holderHRP = holder.Character and holder.Character:FindFirstChild("HumanoidRootPart")
        local localHRP  = getLocalHRP()
        if not holderHRP or not localHRP then return end

        local currHolder = holderHRP.Position
        local currLocal  = localHRP.Position

        if prevHolderPos and prevLocalPos then
            local holderJumped        = (currHolder - prevHolderPos).Magnitude
            local holderNowAtMyOldPos = (currHolder - prevLocalPos).Magnitude < _abs_SWAP_RADIUS
            local iMoved              = (currLocal  - prevLocalPos).Magnitude > _abs_LOCAL_MOVED_MIN

            if holderJumped > _abs_HOLDER_JUMP_MIN
               and holderNowAtMyOldPos
               and iMoved
               and not localJustFired then
                hitCooldowns[holder.Name] = tick()
                task.spawn(function() swapBack(holder) end)
            end
        end

        prevHolderPos = currHolder
        prevLocalPos  = currLocal
    end)
end)

-- ── ANTI-RAGDOLL (HUB PVP) ───────────────────────────────────────────────────
local _arv_RunService = game:GetService("RunService")
local _arv_LP         = Players.LocalPlayer

local AntiRagdoll = { connections = {}, running = false }

AntiRagdoll.forceBackpack = function()
    if not AntiRagdoll.running then return end
    local gui = _arv_LP:FindFirstChild("PlayerGui")
    if not gui then return end
    local backpackGui = gui:FindFirstChild("BackpackGui")
    if not backpackGui then return end
    local backpack = backpackGui:FindFirstChild("Backpack")
    if not backpack then return end
    backpack.Visible = true
    if not backpack:FindFirstChild("ForceConnection") then
        local tag = Instance.new("BoolValue")
        tag.Name   = "ForceConnection"
        tag.Parent = backpack
        backpack:GetPropertyChangedSignal("Visible"):Connect(function()
            if not AntiRagdoll.running then return end
            if not backpack.Visible then backpack.Visible = true end
        end)
    end
end

AntiRagdoll.removeRagdollConstraints = function(char)
    for _, d in ipairs(char:GetDescendants()) do
        if d:IsA("BallSocketConstraint") or d:IsA("HingeConstraint")
            or d:IsA("NoCollisionConstraint")
            or (d:IsA("Attachment") and d.Name:find("RagdollAttachment")) then
            d:Destroy()
        end
    end
end

AntiRagdoll.resetCharacter = function(char)
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    local rootPart = char:FindFirstChild("HumanoidRootPart")
    if rootPart then
        rootPart.Anchored = false
        rootPart.Velocity  = Vector3.zero
    end
    if humanoid then
        for _, obj in ipairs(char:GetDescendants()) do
            if obj:IsA("Motor6D") and obj.Enabled == false then
                obj.Enabled = true
            end
        end
        humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,     false)
        humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        humanoid.PlatformStand = false
        humanoid.Sit           = false
        if humanoid.Health > 0 then
            humanoid:ChangeState(Enum.HumanoidStateType.Running)
        end
        workspace.CurrentCamera.CameraSubject = humanoid
    end
end

AntiRagdoll.onCharacterAdded_AR = function(char)
    char:WaitForChild("HumanoidRootPart")
    local humanoid = char:WaitForChild("Humanoid")

    AntiRagdoll.connections.charDescAdded = char.DescendantAdded:Connect(function(obj)
        if not AntiRagdoll.running then return end
        if obj:IsA("BallSocketConstraint") or obj:IsA("HingeConstraint")
            or obj:IsA("NoCollisionConstraint")
            or (obj:IsA("Attachment") and obj.Name:find("RagdollAttachment")) then
            task.defer(function()
                if not AntiRagdoll.running then return end
                if obj.Parent then obj:Destroy() end
            end)
        end
    end)
    AntiRagdoll.connections.platformStand = humanoid:GetPropertyChangedSignal("PlatformStand"):Connect(function()
        if not AntiRagdoll.running then return end
        if humanoid.PlatformStand then
            task.defer(function()
                if not AntiRagdoll.running then return end
                AntiRagdoll.resetCharacter(char)
                AntiRagdoll.removeRagdollConstraints(char)
            end)
        end
    end)
    AntiRagdoll.removeRagdollConstraints(char)
    AntiRagdoll.resetCharacter(char)
end

AntiRagdoll.enable = function()
    if AntiRagdoll.running then return end
    AntiRagdoll.running = true
    local _arTick = 0
    AntiRagdoll.connections.heartbeat = _arv_RunService.Heartbeat:Connect(function(dt)
        _arTick = _arTick + dt
        if _arTick < 0.1 then return end
        _arTick = 0
        local char = _arv_LP.Character
        if not char then return end
        local hum  = char:FindFirstChildOfClass("Humanoid")
        local root = char:FindFirstChild("HumanoidRootPart")
        if not (hum and root) then return end
        local s = hum:GetState()
        local ragdolled = (s == Enum.HumanoidStateType.Physics
            or s == Enum.HumanoidStateType.Ragdoll
            or s == Enum.HumanoidStateType.FallingDown)
        local endTime = _arv_LP:GetAttribute("RagdollEndTime")
        if endTime and (endTime - workspace:GetServerTimeNow()) > 0 then
            ragdolled = true
        end
        if ragdolled then
            pcall(function() _arv_LP:SetAttribute("RagdollEndTime", workspace:GetServerTimeNow()) end)
            AntiRagdoll.removeRagdollConstraints(char)
            for _, obj in ipairs(char:GetDescendants()) do
                if obj:IsA("Motor6D") and obj.Enabled == false then
                    obj.Enabled = true
                end
            end
            if hum.Health > 0 then hum:ChangeState(Enum.HumanoidStateType.Running) end
            workspace.CurrentCamera.CameraSubject = hum
            root.Anchored = false
            root.Velocity  = Vector3.zero
        end
    end)
    AntiRagdoll.connections.charAdded = _arv_LP.CharacterAdded:Connect(function(char)
        task.wait(1)
        AntiRagdoll.forceBackpack()
        AntiRagdoll.onCharacterAdded_AR(char)
    end)
    if _arv_LP.Character then AntiRagdoll.onCharacterAdded_AR(_arv_LP.Character) end
    task.spawn(function()
        while AntiRagdoll.running do
            task.wait(0.5)
            AntiRagdoll.forceBackpack()
        end
    end)
end

AntiRagdoll.disable = function()
    AntiRagdoll.running = false
    for _, conn in pairs(AntiRagdoll.connections) do
        if conn then pcall(function() conn:Disconnect() end) end
    end
    AntiRagdoll.connections = {}
    pcall(function()
        local char = _arv_LP.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,     true)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        end
    end)
end

