    -- Min Gen to TP (in millions, e.g. "500" = 500M)
    local _minGenBox = makeTpNumInput("Min Gen to TP (M)", y, (fe.tpMinMPS or 0))
    y = y + _TP_ROW + _TP_GAP
    _minGenBox.FocusLost:Connect(function()
        local v = tonumber(_minGenBox.Text)
