        end
    end)

    -- ── Movement section ─────────────────────────────────────────────────
    makeSectionLabel("MOVEMENT", y); y = y + 20

    local _preRiseBtn, _preRiseSet = makeTpToggle("Pre-rise before move", y, fe.preRise == true)
    y = y + _TP_ROW + _TP_GAP
    _preRiseBtn.MouseButton1Click:Connect(function()
        local fe2 = _G.FlashExtra
